"use strict";

document.addEventListener("DOMContentLoaded", function () {
    var TabItems = document.querySelectorAll(".joe_config__aside .item");
    var Notice = document.querySelector(".joe_config__notice");
    var Version = document.querySelector("#joe_version");
    var Form = document.querySelector(".joe_config > form");
    var Content = document.querySelectorAll(".joe_content");

    // Tab 切换逻辑
    TabItems.forEach(function (item) {
        item.addEventListener("click", function () {
            sessionStorage.setItem("su_config_current", item.getAttribute("data-current"));
            TabItems.forEach(function (_item) {
                return _item.classList.remove("active");
            });
            item.classList.add("active");

            if ("joe_notice" === item.getAttribute("data-current")) {
                Notice.style.display = "block";
                Form.style.display = "none";
            } else {
                Form.style.display = "block";
                Notice.style.display = "none";
            }

            Content.forEach(function (_item) {
                _item.style.display = "none";
                if (_item.classList.contains(item.getAttribute("data-current"))) {
                    _item.style.display = "block";
                }
            });
        });
    });

    // 强制默认显示"使用说明"，清除上次保存的 tab
    sessionStorage.removeItem("su_config_current");
    TabItems.forEach(function (_item) {
        return _item.classList.remove("active");
    });
    TabItems[0].classList.add("active");
    Notice.style.display = "block";
    Form.style.display = "none";
    Content.forEach(function (_item) {
        _item.style.display = "none";
    });

    // 版本信息展示（从后端获取版本号）
    var currentVersion = Version ? Version.getAttribute("data-version") || Version.innerHTML : "未知";
    var versionHtml = '<p class="title">当前版本：' + currentVersion + '</p>';
    if (Notice.querySelector(".title")) {
        Notice.querySelector(".title").insertAdjacentHTML("afterend", versionHtml);
    }
});
